using System;
using System.Linq;
using System.IO;
using System.Text.Json;
using Deception.Core;
using Deception.PolyModAdapter;
using U=Polytopia.Data.UnitData.Type;
using A=Polytopia.Data.UnitAbility.Type;
namespace Deception.Tests {
 public static class ConcealmentTests {
 static int Cases,Assertions;static void Check(bool b,string why){Assertions++;if(!b)throw new Exception(why);}static void Test(string name,Action a){try{a();Cases++;}catch(Exception e){throw new Exception(name,e);}}
 static LedgerAppearance Appearance(string form,bool hidden=false)=>new(form,new("imperius","default"),new("imperius","default"),new("imperius","default"),7,50,50,false,hidden?ApparentConcealment.Hidden:ApparentConcealment.Visible,-1,hidden?new[]{"Invisible","Poisoned"}:new[]{"Poisoned"});
 static (GameState,UnitState) Start(string form="cloak",U actual=U.warrior,bool hidden=false,bool independent=true,bool mimic=false){NativeDisguiseConcealment.Clear();NativeLedgerState.Fail=false;NativeRegroupSession.Faults=0;var s=new GameState();var u=new UnitState{id=1,type=actual};u.effects.Add(UnitEffect.Frozen);if(hidden)u.effects.Add(UnitEffect.Invisible);s.Map.Tiles[(0,0)]=new(){unit=u};s.Players[1]=new(){Id=1};s.Players[2]=new(){Id=2};var a=independent?Appearance(form,hidden):null;var l=new NativeIdentityLedger(Guid.Parse("a9c5de32-889f-43b6-84bb-7cd209265e37"),2,1,new[]{new LedgerUnit(1,1,true,mimic?LedgerActualKind.Mimic:LedgerActualKind.Genuine,independent,a,PaidInvestmentKind.Known,3)},Array.Empty<LedgerReceipt>());NativeGameStateEnvelope.Set(s,0,NativeIdentityLedgerCodec.Encode(l,0));GameManager.GameState=s;GameManager.Client=new(){Player=s.Players[2]};return(s,u);}
 static LedgerUnit Row(GameState s)=>NativeIdentityLedgerCodec.Decode(NativeGameStateEnvelope.Get(s)!.Bytes(),0).Units[0];
 static bool Ability(UnitState u,A a){bool v=UnitDataExtensions.HasAbility(u,a);NativeDisguiseConcealment.AfterAbility(u,a,ref v);return v;}
 static bool Warning(GameState s,UnitState u,byte id){bool v=u.IsInvisible(s,id);NativeDisguiseConcealment.AfterInvisibleState(u,s,id,ref v);return v;}
 static bool UiWarning(UnitState u,PlayerState p){bool v=u.IsInvisible(p);NativeDisguiseConcealment.AfterInvisiblePlayer(u,p,ref v);return v;}
 public static int Run(){try{
 Test("native signatures bind",()=>{NativeDisguiseConcealment.Install(new HarmonyLib.Harmony());Check(true,"all fixture signatures");});
 foreach(bool hidden in new[]{false,true})Test("effects only invisible "+hidden,()=>{var(s,u)=Start(hidden:true);var old=u.effects;var copy=(Il2CppSystem.Collections.Generic.List<UnitEffect>)NativeDisguiseConcealment.WithConcealment(old,Appearance("cloak",hidden));Check(!ReferenceEquals(old,copy)&&old.Contains(UnitEffect.Invisible),"original not mutated");Check(copy.Contains(UnitEffect.Invisible)==hidden&&copy.Contains(UnitEffect.Frozen),"selected mechanics and actual frozen retained");Check(u.health==70&&!u.moved&&!u.attacked,"no body or budget changes");});
 Test("genuine reveal becomes visible",()=>{var(s,u)=Start(hidden:true);var copy=(Il2CppSystem.Collections.Generic.List<UnitEffect>)NativeDisguiseConcealment.WithConcealment(u.effects,null);Check(!copy.Contains(UnitEffect.Invisible)&&copy.Contains(UnitEffect.Frozen),"only invisible removed");});
 Test("malformed hidden snapshot refused",()=>{var(s,u)=Start();try{NativeDisguiseConcealment.WithConcealment(u.effects,Appearance("cloak") with{Concealment=ApparentConcealment.Hidden});throw new Exception("missing denial");}catch(InvalidDataException){}Check(u.effects.Count==1,"unchanged");});
 foreach(string form in new[]{"cloak","mermaidcloak","cloak_boat"})Test("scoped native hide "+form,()=>{var(s,u)=Start(form);Check(!Ability(u,A.Hide),"outside move genuine rules");NativeDisguiseConcealment.BeforeMove(new MoveCommand{UnitId=1},s,out var scope);Check(Ability(u,A.Hide)&&!Ability(u,A.Infiltrate)&&!Ability(u,A.Scout),"only hide copied");var foreign=new UnitState{id=1};Check(!Ability(foreign,A.Hide),"exact unit only");NativeDisguiseConcealment.MoveFinished(null,scope);Check(!Ability(u,A.Hide),"scope gone");});
 Test("actual cloak noncloak mask retains native readiness",()=>{var(s,u)=Start("warrior",U.cloak);NativeDisguiseConcealment.BeforeMove(new MoveCommand{UnitId=1},s,out var scope);Check(Ability(u,A.Hide)&&Ability(u,A.Infiltrate),"real native readiness and active power preserved");NativeDisguiseConcealment.MoveFinished(null,scope);Check(Ability(u,A.Hide),"outside scoped native predicate unchanged");});
 Test("nested move and exception cleanup",()=>{var(s,u)=Start();NativeDisguiseConcealment.BeforeMove(new MoveCommand{UnitId=1},s,out var outer);NativeDisguiseConcealment.BeforeMove(new MoveCommand{UnitId=1},s,out var inner);var error=new Exception("native");Check(ReferenceEquals(NativeDisguiseConcealment.MoveFinished(error,inner),error)&&Ability(u,A.Hide),"nested restores outer");NativeDisguiseConcealment.MoveFinished(error,outer);Check(!Ability(u,A.Hide),"exception restores native");});
 Test("unowned move inert",()=>{var(s,u)=Start();s.Owned=false;NativeDisguiseConcealment.BeforeMove(new MoveCommand{UnitId=1},s,out var scope);Check(scope is null&&!Ability(u,A.Hide),"no enrollment");});
 Test("removed root cannot inherit scope",()=>{var(s,u)=Start();NativeDisguiseConcealment.BeforeMove(new MoveCommand{UnitId=1},s,out var scope);s.Map.Tiles[(0,0)].unit=null;Check(!Ability(u,A.Hide),"no stale unit");NativeDisguiseConcealment.MoveFinished(null,scope);});
 foreach(bool remove in new[]{true,false})Test("movement shed/replacement invalidates borrowed Hide "+remove,()=>{var(s,u)=Start();NativeDisguiseConcealment.BeforeMove(new MoveCommand{UnitId=1},s,out var scope);var snapshot=NativeGameStateEnvelope.Get(s)!;var ledger=NativeIdentityLedgerCodec.Decode(snapshot.Bytes(),snapshot.Revision);var row=ledger.Units[0];ledger=ledger with{Units=new[]{row with{Independent=!remove,Appearance=remove?null:Appearance("warrior")}}};NativeGameStateEnvelope.Set(s,snapshot.Revision,NativeIdentityLedgerCodec.Encode(ledger,snapshot.Revision));Check(!Ability(u,A.Hide),"stale MoveCommand mask cannot queue a borrowed Hide after reveal");NativeDisguiseConcealment.MoveFinished(null,scope);});
 foreach(string form in new[]{"cloak","mermaidcloak","cloak_boat"})Test("native hide mirrors without fake power "+form,()=>{var(s,u)=Start(form);var old=u.effects;var action=new HideAction();bool run=NativeDisguiseConcealment.BeforeHide(action,s,out var scope);if(run)action.Execute(s);NativeDisguiseConcealment.AfterEffect(scope,run);Check(run&&u.effects.Contains(UnitEffect.Invisible)&&u.attacked,"native hide cost retained");Check(!old.Contains(UnitEffect.Invisible)&&!ReferenceEquals(old,u.effects),"no old list mutation");Check(Row(s).Appearance!.Concealment==ApparentConcealment.Hidden&&Row(s).Appearance!.Effects.SequenceEqual(new[]{"Invisible","Poisoned"}),"snapshot mirror preserves apparent poison independently");Check(u.effects.Contains(UnitEffect.Frozen)&&u.type==U.warrior&&u.health==70,"actual status/body intact");});
 Test("native detection reveals concealment only",()=>{var(s,u)=Start(hidden:true,mimic:true);var action=new RevealAction();NativeDisguiseConcealment.BeforeReveal(action,s,out var scope);action.Execute(s);NativeDisguiseConcealment.AfterEffect(scope,true);Check(!u.effects.Contains(UnitEffect.Invisible)&&Row(s).Independent,"detected never exposes true identity");Check(Row(s).Appearance!.Form=="cloak"&&Row(s).Appearance!.Effects.SequenceEqual(new[]{"Poisoned"})&&!u.attacked,"type and flags retained");});
 Test("noncloak pending hide blocked",()=>{var(s,u)=Start("warrior",U.warrior);bool run=NativeDisguiseConcealment.BeforeHide(new HideAction(),s,out var scope);NativeDisguiseConcealment.AfterEffect(scope,run);Check(!run&&scope is null&&!u.attacked&&!u.effects.Contains(UnitEffect.Invisible),"stale native hide cannot expose mask");bool valid=true;string e="";NativeDisguiseConcealment.AfterHideValid(new HideCommand(),s,ref valid,ref e);Check(!valid&&e.Length>0,"manual hide validation aligned");});
 Test("ordinary native cloak untouched",()=>{var(s,u)=Start("cloak",U.cloak,independent:false);bool run=NativeDisguiseConcealment.BeforeHide(new HideAction(),s,out var scope);Check(run&&scope is null,"ordinary native action");bool v=true;string e="";NativeDisguiseConcealment.AfterHideValid(new HideCommand(),s,ref v,ref e);Check(v,"ordinary manual hide");});
 Test("failed native action faults without ledger publication",()=>{var(s,u)=Start();NativeDisguiseConcealment.BeforeHide(new HideAction(),s,out var scope);var bytes=NativeGameStateEnvelope.Get(s)!.Bytes();var error=new Exception("native failure");Check(ReferenceEquals(NativeDisguiseConcealment.EffectFinished(error,scope),error)&&NativeRegroupSession.Faults==1,"failure remains visible");Check(NativeGameStateEnvelope.Get(s)!.Bytes().SequenceEqual(bytes),"no premature private success");});
 Test("validation failure cannot publish",()=>{var(s,u)=Start();var action=new HideAction();NativeDisguiseConcealment.BeforeHide(action,s,out var scope);action.Execute(s);var bytes=NativeGameStateEnvelope.Get(s)!.Bytes();NativeLedgerState.Fail=true;try{NativeDisguiseConcealment.AfterEffect(scope,true);throw new Exception("missing error");}catch(InvalidDataException e){NativeDisguiseConcealment.EffectFinished(e,scope);}Check(NativeRegroupSession.Faults==1&&NativeGameStateEnvelope.Get(s)!.Bytes().SequenceEqual(bytes),"native failure stops persistence");});
 foreach(U actual in new[]{U.cloak,U.mermaidcloak,U.cloak_boat})Test("hostile eye only in warning scope "+actual,()=>{var(s,u)=Start("warrior",actual);var detector=new UnitState{id=2,owner=2,coordinates=new(1,0)};s.Map.Tiles[(1,0)]=new(){unit=detector};Check(!Warning(s,u,2)&&!u.IsInvisible(s,2),"public visible before");NativeDisguiseConcealment.BeforeDetecting(detector,s,out var scope);Check(Warning(s,u,2)&&!Warning(s,u,1),"hostile warning only");Check(!u.IsInvisible(s,2)&&!u.effects.Contains(UnitEffect.Invisible),"warning never hides body");NativeDisguiseConcealment.WarningFinished(null,scope);Check(!Warning(s,u,2),"public restored");});
 Test("eye respects peace",()=>{var(s,u)=Start("warrior",U.cloak);s.Players[2].Peace.Add(1);NativeDisguiseConcealment.BeforeWarningUi(out var scope);Check(!UiWarning(u,s.Players[2]),"no friendly warning");NativeDisguiseConcealment.WarningFinished(null,scope);});
 Test("eye respects owner",()=>{var(s,u)=Start("warrior",U.cloak);GameManager.Client!.Player=s.Players[1];NativeDisguiseConcealment.BeforeWarningUi(out var scope);Check(!UiWarning(u,s.Players[1]),"no own warning");NativeDisguiseConcealment.WarningFinished(null,scope);});
 Test("ui eye exact viewer and state",()=>{var(s,u)=Start("warrior",U.cloak);NativeDisguiseConcealment.BeforeWarningUi(out var scope);Check(UiWarning(u,s.Players[2]),"actual masked cloak warning");Check(!UiWarning(u,new PlayerState{Id=2}),"wrong viewer instance");GameManager.GameState=new();Check(!UiWarning(u,s.Players[2]),"changed displayed world");NativeDisguiseConcealment.WarningFinished(null,scope);});
 Test("warning backend wrong state inert",()=>{var(s,u)=Start("warrior",U.cloak);var d=new UnitState{id=2,owner=2,coordinates=new(1,0)};s.Map.Tiles[(1,0)]=new(){unit=d};NativeDisguiseConcealment.BeforeDetecting(d,s,out var scope);var other=new GameState();other.Players[2]=s.Players[2];Check(!Warning(other,u,2),"explicit sibling identity");NativeDisguiseConcealment.WarningFinished(null,scope);});
 foreach(var pair in new[]{("warrior",U.warrior,false),("cloak",U.warrior,false),("cloak",U.cloak,false),("cloak",U.dcp_mimic_cloak,true)})Test("no extra noncloak/visible warning "+pair,()=>{var(s,u)=Start(pair.Item1,pair.Item2,mimic:pair.Item3);NativeDisguiseConcealment.BeforeWarningUi(out var scope);Check(!UiWarning(u,s.Players[2]),"no invented detection on visible normal/fake cloak");NativeDisguiseConcealment.WarningFinished(null,scope);});
 Test("hidden apparent cloak native warning remains",()=>{var(s,u)=Start(hidden:true);NativeDisguiseConcealment.BeforeWarningUi(out var scope);Check(UiWarning(u,s.Players[2])&&!UiWarning(u,s.Players[1]),"actual functional concealment drives native source");NativeDisguiseConcealment.WarningFinished(null,scope);});
 Test("unbound ui inert",()=>{var(s,u)=Start("warrior",U.cloak);s.Owned=false;NativeDisguiseConcealment.BeforeWarningUi(out var scope);Check(scope is null&&!UiWarning(u,s.Players[2]),"no warning enrollment");});
 Test("clear removes active scopes",()=>{var(s,u)=Start("warrior",U.cloak);NativeDisguiseConcealment.BeforeWarningUi(out var scope);NativeDisguiseConcealment.Clear();Check(!UiWarning(u,s.Players[2]),"world cleanup");});
 Test("clear cannot resurrect nested scopes",()=>{var(s,u)=Start("warrior",U.cloak);NativeDisguiseConcealment.BeforeWarningUi(out var outer);NativeDisguiseConcealment.BeforeWarningUi(out var inner);NativeDisguiseConcealment.Clear();NativeDisguiseConcealment.WarningFinished(null,inner);Check(!UiWarning(u,s.Players[2]),"old outer warning not resurrected");NativeDisguiseConcealment.WarningFinished(null,outer);});
 Test("replacement UI client invalidates scope",()=>{var(s,u)=Start("warrior",U.cloak);NativeDisguiseConcealment.BeforeWarningUi(out var scope);GameManager.Client=new(){Player=s.Players[2]};Check(!UiWarning(u,s.Players[2]),"new client cannot borrow warning scope");NativeDisguiseConcealment.WarningFinished(null,scope);});
 Console.WriteLine(JsonSerializer.Serialize(new{passed=true,cases=Cases,assertions=Assertions,nativeGame="NOT RUN"}));return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
 }
}
